iloc[-1])\n    prev_low = float(low.iloc[-2])\n    prev_high = float(high.iloc[-2])\n\n    # Bullish FVG + Prior Liquidity Low Sweep in Uptrend\n    bull_fvg = float(low.iloc[-1]) > float(high.iloc[-3])\n    swept_low = (prev_low < prior_low) and (c_close > prior_low)\n    if fast.iloc[-1] > slow.iloc[-1] and swept_low and bull_fvg and cur_rsi < 68:\n        sl_dist = max(c_close - prev_low, 0.5 * float(cur_atr)) + (params.get(\"atr_sl_mult\", 1.4) * float(cur_atr) * 0.35)\n        sl = c_close - sl_dist\n        tp1 = c_close + sl_dist * params.get(\"rr_tp1\", 1.5)\n        tp2 = c_close + sl_dist * params.get(\"rr_tp2\", 3.2)\n        return {\n            \"signal\": \"BUY\",\n            \"mode\": \"SCALP\",\n            \"entry\": c_close,\n            \"sl\": sl,\n            \"tp1\": tp1,\n            \"tp2\": tp2,\n            \"reason\": \"EMA uptrend + liquidity low sweep + bullish FVG displacement\",\n        }\n\n    # Bearish FVG + Prior Liquidity High Sweep in Downtrend\n    bear_fvg = float(high.iloc[-1]) < float(low.iloc[-3])\n    swept_high = (prev_high > prior_high) and (c_close < prior_high)\n    if fast.iloc[-1] < slow.iloc[-1] and swept_high and bear_fvg and cur_rsi > 32:\n        sl_dist = max(prev_high - c_close, 0.5 * float(cur_atr)) + (params.get(\"atr_sl_mult\", 1.4) * float(cur_atr) * 0.35)\n        sl = c_close + sl_dist\n        tp1 = c_close - sl_dist * params.get(\"rr_tp1\", 1.5)\n        tp2 = c_close - sl_dist * params.get(\"rr_tp2\", 3.2)\n        return {\n            \"signal\": \"SELL\",\n            \"mode\": \"SCALP\",\n            \"entry\": c_close,\n            \"sl\": sl,\n            \"tp1\": tp1,\n            \"tp2\": tp2,\n            \"reason\": \"EMA downtrend + liquidity high sweep + bearish FVG displacement\",\n        }\n\n    return None',NULL,0,'2026-11-16 22:20:14'),(11,'H1/H4 EMA Trend Pullback + ATR',NULL,'SWING','DEFAULT_PARAMS = {\n    \"fast_ema\": 21,\n    \"slow_ema\": 50,\n    \"atr_period\": 14,\n    \"atr_sl_mult\": 1.5,\n    \"rr_tp1\": 1.5,\n    \"rr_tp2\": 3.0,\n}\n\ndef evaluate(df, params):\n    \"\"\"\n    H1/H4 EMA Trend Pullback + ATR Strategy (SWING).\n    Trades institutional trend continuation when price pulls back into the dynamic\n    value zone of EMA21 / EMA50 and prints an ATR-confirmed price rejection.\n    \"\"\"\n    if len(df) < params.get(\"slow_ema\", 50) + 10:\n        return None\n\n    close_series = df[\"close\"]\n    fast = ema(close_series, params.get(\"fast_ema\", 21))\n    slow = ema(close_series, params.get(\"slow_ema\", 50))\n    atr_vals = atr(df, params.get(\"atr_period\", 14))\n\n    curr_close = float(close_series.iloc[-1])\n    curr_low = float(df[\"low\"].iloc[-1])\n    curr_high = float(df[\"high\"].iloc[-1])\n    curr_fast = float(fast.iloc[-1])\n    curr_slow = float(slow.iloc[-1])\n    curr_atr = float(atr_vals.iloc[-1])\n\n    sl_dist = curr_atr * params.get(\"atr_sl_mult\", 1.5)\n\n    # Uptrend Condition: Fast EMA > Slow EMA and price pulled back to Fast EMA\n    if curr_fast > curr_slow and curr_low <= curr_fast and curr_close > curr_fast:\n        entry = curr_close\n        sl = round(curr_low - sl_dist, 2)\n        risk = entry - sl\n        if risk > 0:\n            tp1 = round(entry + (risk * params.get(\"rr_tp1\", 1.5)), 2)\n            tp2 = round(entry + (risk * params.get(\"rr_tp2\", 3.0)), 2)\n            return {\n                \"signal\": \"BUY\",\n                \"mode\": \"SWING\",\n                \"entry\": entry,\n                \"sl\": sl,\n                \"tp1\": tp1,\n                \"tp2\": tp2,\n                \"reason\": \"Uptrend EMA value zone pullback rejection confirmed.\",\n            }\n\n    # Downtrend Condition: Fast EMA < Slow EMA and price pulled back to Fast EMA\n    elif curr_fast < curr_slow and curr_high >= curr_fast and curr_close < curr_fast:\n        entry = curr_close\n        sl = round(curr_high + sl_dist, 2)\n        risk = sl - entry\n        if risk > 0:\n         